#include "backends/cpu/cpu_backend.hpp"
#include <iostream>
#include <cstring>
#include <cstdint>
int main() {
    backend::CpuBackend cpu;
    uint32_t rng=12345;
    auto next=[&](){rng=rng*1664525u+1013904223u; return float(int(rng>>8)-8388608)/8388608.0f;};
    size_t tested=0;
    for(size_t ni: {size_t(1),size_t(7),size_t(8),size_t(10),size_t(31),size_t(32),size_t(33),size_t(42),size_t(63),size_t(64),size_t(65),size_t(129),size_t(1024),size_t(3072)}) {
        for(size_t no: {size_t(1),size_t(2),size_t(3),size_t(13),size_t(25),size_t(257)}) {
            std::vector<float> w(ni*no),x(ni),y(no),expected(no);
            for(auto& f:w)f=next();for(auto& f:x)f=next();
            for(size_t o=0;o<no;++o) expected[o]=backend::CpuBackend::dot_f32(w.data()+o*ni,x.data(),ni);
            for(int nt: {1,4,6}) {
                cpu.set_threads(nt);
                cpu.matmul(gguf::GGML_TYPE_F32,reinterpret_cast<const uint8_t*>(w.data()),x.data(),y.data(),ni,no,1);
                for(size_t o=0;o<no;++o) {
                    if(std::memcmp(&y[o],&expected[o],sizeof(float))) {std::cerr<<ni<<" "<<no<<" "<<nt<<" "<<o<<"\n"; return 1;}
                    ++tested;
                }
            }
        }
    }
    std::cout<<tested<<" matrix outputs byte-identical to single-row control\n";
}

