+    static void dot_f32_pair(const float* a, const float* b, const float* x,
+                             size_t n, float* out) {
+        __m256 a0 = _mm256_setzero_ps(), a1 = _mm256_setzero_ps();
+        __m256 a2 = _mm256_setzero_ps(), a3 = _mm256_setzero_ps();
+        __m256 b0 = _mm256_setzero_ps(), b1 = _mm256_setzero_ps();
+        __m256 b2 = _mm256_setzero_ps(), b3 = _mm256_setzero_ps();
+        size_t i = 0;
+        for (; i + 32 <= n; i += 32) {
+            const __m256 x0 = _mm256_loadu_ps(x + i);
+            const __m256 x1 = _mm256_loadu_ps(x + i + 8);
+            const __m256 x2 = _mm256_loadu_ps(x + i + 16);
+            const __m256 x3 = _mm256_loadu_ps(x + i + 24);
+            a0 = _mm256_fmadd_ps(_mm256_loadu_ps(a + i), x0, a0);
+            b0 = _mm256_fmadd_ps(_mm256_loadu_ps(b + i), x0, b0);
+            a1 = _mm256_fmadd_ps(_mm256_loadu_ps(a + i + 8), x1, a1);
+            b1 = _mm256_fmadd_ps(_mm256_loadu_ps(b + i + 8), x1, b1);
+            a2 = _mm256_fmadd_ps(_mm256_loadu_ps(a + i + 16), x2, a2);
+            b2 = _mm256_fmadd_ps(_mm256_loadu_ps(b + i + 16), x2, b2);
+            a3 = _mm256_fmadd_ps(_mm256_loadu_ps(a + i + 24), x3, a3);
+            b3 = _mm256_fmadd_ps(_mm256_loadu_ps(b + i + 24), x3, b3);
+        }
+        __m256 aa = _mm256_add_ps(_mm256_add_ps(a0, a1), _mm256_add_ps(a2, a3));
+        __m256 bb = _mm256_add_ps(_mm256_add_ps(b0, b1), _mm256_add_ps(b2, b3));
+        for (; i + 8 <= n; i += 8) {
+            const __m256 xv = _mm256_loadu_ps(x + i);
+            aa = _mm256_fmadd_ps(_mm256_loadu_ps(a + i), xv, aa);
+            bb = _mm256_fmadd_ps(_mm256_loadu_ps(b + i), xv, bb);
+        }
+        float ya = hsum256(aa), yb = hsum256(bb);
+        for (; i < n; ++i) { ya += a[i] * x[i]; yb += b[i] * x[i]; }
+        out[0] = ya; out[1] = yb;
